'use strict';

/**
 * OCI Signature v1 request signer (zero dependency).
 *
 * Implements the Oracle Cloud Infrastructure "Signature" auth scheme —
 * an RSA-SHA256 signature over a canonical string derived from the request.
 * See: https://docs.oracle.com/iaas/Content/API/Concepts/signingrequests.htm
 *
 * Compatible with the OCI Vault Secrets API (secrets.vaults.<region>):
 *   - GetSecretBundle          GET  /20190301/secretbundles/{secretId}
 *   - GetSecretBundleByName    POST /20190301/secretbundles/actions/getByName?secretName=&vaultId=
 *   - CreateSecret             POST /20190301/secrets
 *   - CreateSecretVersion      POST /20190301/secrets/{secretId}/versions
 */

const crypto = require('crypto');

/**
 * Build the canonical (request-target) value.
 * Lowercase method + space + path with the query string (verbatim order).
 * @param {string} method
 * @param {string} path  e.g. /20190301/secretbundles/...
 * @param {URLSearchParams|string} [query]
 */
function requestTarget(method, path, query) {
  let target = `${method.toLowerCase()} ${path}`;
  const qs = query ? String(query) : '';
  if (qs && qs.length) target += `?${qs}`;
  return target;
}

/**
 * Construct and sign an OCI request.
 *
 * @param {object} opts
 * @param {string} opts.tenancyOcid    tenancy OCID (keyId first segment)
 * @param {string} opts.userOcid       user OCID (keyId second segment)
 * @param {string} opts.fingerprint    API key fingerprint (keyId third segment)
 * @param {string} opts.privateKeyPem  RSA private key PEM used to sign
 * @param {string} opts.region         OCI region e.g. us-ashburn-1
 * @param {string} opts.method         HTTP method (GET/POST)
 * @param {string} opts.path           API path (starts with /)
 * @param {URLSearchParams|string} [opts.query]
 * @param {string} [opts.body]         request body (POST)
 * @param {string} [opts.contentType]  Content-Type for POST body
 * @param {object} [opts.extraHeaders] additional headers to send
 * @returns {{headers: object, body?: Buffer|string}}
 */
function signRequest(opts) {
  const {
    tenancyOcid, userOcid, fingerprint, privateKeyPem, region,
    method, path, query, body, contentType, extraHeaders,
  } = opts;

  if (!tenancyOcid || !userOcid || !fingerprint || !privateKeyPem || !region) {
    throw new Error(
      'OCI_SIGNER_MISSING_CONFIG: need tenancyOcid, userOcid, fingerprint, privateKeyPem, region'
    );
  }

  const rfc7231Date = new Date().toUTCString(); // "Date" header format
  const host = `secrets.vaults.${region}.oci.oraclecloud.com`;
  const methodU = method.toUpperCase();
  // OCI: POST/PUT (and GET/DELETE with a body) must sign body headers;
  // content-length/x-content-sha256 are required even for an empty body.
  const hasBody = methodU === 'POST' || methodU === 'PUT' || methodU === 'PATCH' || body !== undefined;

  const headers = { host, date: rfc7231Date };
  let signingHeaders = ['(request-target)', 'host', 'date'];

  if (hasBody) {
    const bodyBuf = Buffer.isBuffer(body) ? body : Buffer.from(String(body ?? ''), 'utf8');
    const contentSha256 = crypto.createHash('sha256').update(bodyBuf).digest('base64');
    headers['content-type'] = contentType || 'application/json';
    headers['content-length'] = bodyBuf.length;
    headers['x-content-sha256'] = contentSha256;
    // OCI requires POST/PUT to sign payload headers as well.
    signingHeaders = ['(request-target)', 'host', 'date', 'x-content-sha256', 'content-type', 'content-length'];
  }

  if (extraHeaders) {
    for (const [k, v] of Object.entries(extraHeaders)) {
      const lk = k.toLowerCase();
      if (!Object.prototype.hasOwnProperty.call(headers, lk)) {
        headers[lk] = v;
      }
    }
  }

  const target = requestTarget(method, path, query);
  const headerParts = [];

  // Build the canonical signing string in the order of signingHeaders.
  const signingStringLines = [];
  for (const h of signingHeaders) {
    if (h === '(request-target)') {
      signingStringLines.push(`(request-target): ${target}`);
      headerParts.push('(request-target)');
    } else {
      signingStringLines.push(`${h}: ${headers[h]}`);
      headerParts.push(h);
    }
  }
  const signingString = signingStringLines.join('\n');

  const signature = crypto.sign('sha256', Buffer.from(signingString, 'utf8'), {
    key: privateKeyPem,
    padding: crypto.constants.RSA_PKCS1_PADDING,
  });

  const keyId = `${tenancyOcid}/${userOcid}/${fingerprint}`;
  const authHeader =
    `Signature version="1",keyId="${keyId}",algorithm="rsa-sha256",` +
    `headers="${headerParts.join(' ')}",signature="${signature.toString('base64')}"`;

  headers.authorization = authHeader;

  return { headers, body: hasBody ? Buffer.from(body, 'utf8') : undefined };
}

module.exports = { signRequest, requestTarget };
